#include <iostream>
#include <string>
#include <map>
#include <vector>
#include <functional>
#include <sstream>
#include <regex>
#include <memory>

enum class Role { ADMIN, OPERATOR, VIEWER };

struct User {
    std::string name;
    Role role;
    std::map<std::string, std::string> attributes;
};

struct Container {
    std::string id;
    std::string image;
    std::map<std::string, std::string> labels;
    std::string owner;
};

class ExpressionEngine {
public:
    using Context = std::map<std::string, std::string>;

    static std::string resolve_variable(const std::string& var, const Context& ctx) {
        auto it = ctx.find(var);
        if (it != ctx.end()) return it->second;
        return "";
    }

    static std::string evaluate(const std::string& expr, const Context& ctx) {
        std::string result = expr;
        std::regex var_pattern(R"(\$\{([a-zA-Z_][a-zA-Z0-9_.]*?)\})");
        std::smatch match;
        std::string working = result;
        std::string output;

        while (std::regex_search(working, match, var_pattern)) {
            output += match.prefix().str();
            std::string var_name = match[1].str();
            output += resolve_variable(var_name, ctx);
            working = match.suffix().str();
        }
        output += working;
        return output;
    }
};

class PolicyEngine {
public:
    struct PolicyRule {
        std::string resource_pattern;
        Role minimum_role;
        std::string condition_expr;
    };

    void add_rule(const PolicyRule& rule) {
        rules_.push_back(rule);
    }

    bool check_access(const User& user, const Container& container,
                      const std::string& action) {
        ExpressionEngine::Context ctx = build_context(user, container, action);

        for (const auto& rule : rules_) {
            if (!matches_resource(container.id, rule.resource_pattern))
                continue;
            if (user.role > rule.minimum_role)
                return false;
            if (!rule.condition_expr.empty()) {
                std::string evaluated = ExpressionEngine::evaluate(
                    rule.condition_expr, ctx);
                if (!evaluate_condition(evaluated))
                    return false;
            }
            return true;
        }
        return false;
    }

private:
    std::vector<PolicyRule> rules_;

    ExpressionEngine::Context build_context(const User& user,
                                            const Container& container,
                                            const std::string& action) {
        ExpressionEngine::Context ctx;
        ctx["user.name"] = user.name;
        ctx["user.role"] = role_to_string(user.role);
        ctx["container.owner"] = container.owner;
        ctx["container.image"] = container.image;
        ctx["action"] = action;
        for (const auto& attr : user.attributes) {
            ctx["user.attr." + attr.first] = attr.second;
        }
        for (const auto& label : container.labels) {
            ctx["container.label." + label.first] = label.second;
        }
        return ctx;
    }

    bool matches_resource(const std::string& id, const std::string& pattern) {
        if (pattern == "*") return true;
        return id.find(pattern) != std::string::npos;
    }

    bool evaluate_condition(const std::string& cond) {
        if (cond == "true" || cond == "1") return true;
        if (cond == "false" || cond == "0") return false;
        // equality check: "value == value"
        auto eq_pos = cond.find("==");
        if (eq_pos != std::string::npos) {
            std::string lhs = trim(cond.substr(0, eq_pos));
            std::string rhs = trim(cond.substr(eq_pos + 2));
            return lhs == rhs;
        }
        // non-empty string is truthy
        return !cond.empty();
    }

    std::string trim(const std::string& s) {
        size_t start = s.find_first_not_of(" \t");
        size_t end = s.find_last_not_of(" \t");
        if (start == std::string::npos) return "";
        return s.substr(start, end - start + 1);
    }

    std::string role_to_string(Role r) {
        switch(r) {
            case Role::ADMIN: return "admin";
            case Role::OPERATOR: return "operator";
            case Role::VIEWER: return "viewer";
        }
        return "unknown";
    }
};

class Orchestrator {
public:
    Orchestrator() {
        PolicyEngine::PolicyRule owner_rule;
        owner_rule.resource_pattern = "*";
        owner_rule.minimum_role = Role::OPERATOR;
        owner_rule.condition_expr = "${user.name} == ${container.owner}";
        policy_.add_rule(owner_rule);

        PolicyEngine::PolicyRule admin_rule;
        admin_rule.resource_pattern = "*";
        admin_rule.minimum_role = Role::ADMIN;
        admin_rule.condition_expr = "";
        policy_.add_rule(admin_rule);
    }

    std::string execute_action(const User& user, const std::string& container_id,
                               const std::string& action,
                               const std::string& action_params) {
        auto it = containers_.find(container_id);
        if (it == containers_.end())
            return "error: container not found";

        if (!policy_.check_access(user, it->second, action))
            return "error: access denied";

        if (action == "inspect") {
            return format_inspect(it->second, user);
        } else if (action == "exec") {
            return execute_in_container(it->second, action_params, user);
        }
        return "error: unknown action";
    }

    void register_container(const Container& c) {
        containers_[c.id] = c;
    }

private:
    PolicyEngine policy_;
    std::map<std::string, Container> containers_;

    std::string format_inspect(const Container& c, const User& user) {
        std::ostringstream oss;
        oss << "ID: " << c.id << "\nImage: " << c.image
            << "\nOwner: " << c.owner;
        return oss.str();
    }

    std::string execute_in_container(const Container& c,
                                     const std::string& cmd_template,
                                     const User& user) {
        // Resolve any template variables in the command before execution
        ExpressionEngine::Context ctx;
        ctx["container.id"] = c.id;
        ctx["container.image"] = c.image;
        ctx["user.name"] = user.name;
        for (const auto& label : c.labels) {
            ctx["container.label." + label.first] = label.second;
        }
        for (const auto& attr : user.attributes) {
            ctx["user.attr." + attr.first] = attr.second;
        }

        std::string resolved_cmd = ExpressionEngine::evaluate(cmd_template, ctx);
        // Execute resolved command in container namespace
        return "executed: " + resolved_cmd;
    }
};

int main() {
    Orchestrator orch;

    Container c1;
    c1.id = "web-frontend-01";
    c1.image = "nginx:latest";
    c1.owner = "alice";
    c1.labels["env"] = "production";
    orch.register_container(c1);

    User alice;
    alice.name = "alice";
    alice.role = Role::OPERATOR;
    alice.attributes["team"] = "platform";

    // Normal usage
    std::cout << orch.execute_action(alice, "web-frontend-01", "exec",
                                      "healthcheck --target=${container.id}")
              << std::endl;

    return 0;
}
